import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, mul, add } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Texture } = ctx.THREE;

  // Create container
  const container = new Group();

  // Determine aspect ratio from atlas region (512 x 320)
  const regionWidth = 512;
  const regionHeight = 320;
  const aspect = regionWidth / regionHeight; // 1.6

  // Plane geometry sized to aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic node material (will receive a sampled texture node)
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // Mesh
  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // Load texture asynchronously (function stays synchronous)
  let loadedTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;

    // Compute UV transform for the atlas region
    const img = tex.image;
    if (img) {
      const texW = img.width;
      const texH = img.height;

      const srcX = 0;
      const srcY = 0;
      const srcW = regionWidth;
      const srcH = regionHeight;

      // Three.js texture offset/repeat (Y axis flipped)
      tex.offset.set(srcX / texW, 1 - (srcY + srcH) / texH);
      tex.repeat.set(srcW / texW, srcH / texH);
      tex.needsUpdate = true;
    }

    // Build a node that samples the texture with corrected UVs
    const uvNode = uv(); // default UVs (0‑1)
    const scaledUV = mul(uvNode, vec2(tex.repeat.x, tex.repeat.y));
    const offsetUV = add(scaledUV, vec2(tex.offset.x, tex.offset.y));

    material.map = texture(tex, offsetUV);
    material.needsUpdate = true;
  });

  // Add text label using the font atlas (optional, spec only requires the visual)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: ctx.visualSpec?.colors?.ink ?? '#16161d',
      align: 'center',
    });
    // Center text on the plane
    txt.position.set(0, 0, 0.01);
    container.add(txt);
  }

  // Simple billboard behaviour (always face the camera)
  container.userData.handlers = {
    update(delta, elapsed, camera) {
      if (camera) {
        container.lookAt(camera.position);
      }
    },
  };

  // Cleanup routine
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
    // No GSAP timelines created, but ensure any would be killed
    if (container.userData.handlers?.timeline) {
      container.userData.handlers.timeline.kill();
    }
  };

  return container;
}
